CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE COLLATE NOCASE,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS worlds(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users,name TEXT NOT NULL,description TEXT NOT NULL,seed TEXT NOT NULL,land TEXT NOT NULL,access TEXT NOT NULL,draft TEXT NOT NULL,provider TEXT NOT NULL,ruleset TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(world_id TEXT REFERENCES worlds,user_id TEXT REFERENCES users,role TEXT NOT NULL,PRIMARY KEY(world_id,user_id));
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,world_id TEXT NOT NULL UNIQUE REFERENCES worlds);
CREATE TABLE IF NOT EXISTS invites(token TEXT PRIMARY KEY,room_id TEXT REFERENCES rooms,role TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS characters(world_id TEXT REFERENCES worlds,user_id TEXT REFERENCES users,state TEXT NOT NULL,PRIMARY KEY(world_id,user_id));
CREATE TABLE IF NOT EXISTS builds(world_id TEXT REFERENCES worlds,user_id TEXT REFERENCES users,mode TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(world_id,user_id));
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,world_id TEXT REFERENCES worlds,user_id TEXT REFERENCES users,command_key TEXT NOT NULL,record TEXT NOT NULL,UNIQUE(world_id,user_id,command_key));
CREATE INDEX IF NOT EXISTS event_world ON events(world_id);
CREATE TABLE IF NOT EXISTS definitions(id TEXT PRIMARY KEY,body TEXT NOT NULL);
PRAGMA user_version=1;
